const fs=require('node:fs'),path=require('node:path');
module.exports=dir=>{
 const revision=JSON.parse(fs.readFileSync(path.join(dir,'climax-v2-generation.json'),'utf8'));
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 return {revision,css:'.climax-panel{margin:28px 0;padding:26px;border:1px solid #cdbf9b;border-radius:18px;background:#fffaf0}.climax-panel h2{margin-top:0}.climax-panel p{font-size:13px;line-height:1.8;color:#6f7363}.climax-picks{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.climax-panel select{width:100%;max-width:580px;padding:12px;border:1px solid #d4c9b1;border-radius:8px;background:white}.climax-panel iframe{display:block;width:100%;max-width:760px;height:240px;border:0;margin-top:16px}.climax-panel button{border:1px solid #cabd9d;border-radius:20px;background:white;padding:8px 14px;color:#655332}.climax-panel button[aria-pressed=true]{background:#655332;color:white}.old-climax{font-size:11px;color:#7a8071;padding:10px 0}.old-climax summary{cursor:pointer}',
 html:'<section id="climax-revision" class="climax-panel"><div class="eyebrow">CLIMAX / V2</div><h2>위기가 확실히 느껴지는 클라이맥스</h2><p>명작 14세트 · 전래 10세트. 명작은 현악·관악·타악의 추격감, 전래는 가야금·거문고·대금·해금과 장구·북의 장단으로 제작했습니다. 생성 지시를 반영한 청취 후보이며, 마음에 드는 A/B를 골라 주세요.</p><div class="climax-picks"><button data-climax-genre="classic" aria-pressed="true">명작동화</button><button data-climax-genre="folktale" aria-pressed="false">전래동화 · 동양풍</button></div><label for="climax-select">세트 선택</label><br><select id="climax-select"></select><div class="climax-picks"><button data-climax-candidate="0" aria-pressed="true">후보 A</button><button data-climax-candidate="1" aria-pressed="false">후보 B</button><a id="climax-source" target="_blank" rel="noopener">Suno 원곡 ↗</a></div><strong id="climax-title"></strong><p id="climax-hint">후보를 선택한 뒤 Suno 플레이어의 재생 버튼을 눌러 주세요.</p><iframe id="climax-frame" title="새 클라이맥스 Suno 플레이어" allow="autoplay; encrypted-media; fullscreen" allowfullscreen loading="lazy" referrerpolicy="no-referrer-when-downgrade" hidden></iframe><p>새 곡은 공식 임베드 미리듣기입니다. 다운로드 한도 소진으로 MP3 교체와 동화책 적용은 아직 진행하지 않았습니다. 도입·마지막과 이전 클라이맥스는 아래 세트 카드에서 비교할 수 있습니다.</p></section>',
 js:`
function silenceClimax(){const f=document.getElementById('climax-frame');if(f){f.src='about:blank';f.hidden=true;}}
function showClimax(id,candidate=0){const s=data.climaxRevision.sets.find(x=>x.id===id);if(!s)return;const c=s.candidates[candidate];++playVersion;audio.pause();audio.removeAttribute('src');audio.load();queue=[];at=0;const pf=document.getElementById('pig-frame');if(pf){pf.src='about:blank';pf.hidden=true;document.getElementById('pig-embed-hint').hidden=false;}document.querySelectorAll('[data-climax-genre]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.climaxGenre===s.genre)));const select=document.getElementById('climax-select');select.innerHTML=data.climaxRevision.sets.filter(x=>x.genre===s.genre).map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>').join('');select.value=id;document.querySelectorAll('[data-climax-candidate]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.climaxCandidate===candidate)));document.getElementById('climax-title').textContent=s.name+' · 긴장형 v2 · 후보 '+(candidate?'B':'A')+' · '+c.duration;document.getElementById('climax-source').href=c.url;const f=document.getElementById('climax-frame');f.src=c.url.replace('/song/','/embed/');f.hidden=false;document.getElementById('now').textContent=s.name+' · 새 클라이맥스';document.getElementById('status').textContent='상단 Suno 플레이어에서 재생';['prev','next','toggle'].forEach(id=>document.getElementById(id).disabled=true);}
function enhanceClimaxCards(){if(!data.climaxRevision)return;document.querySelectorAll('#cards [data-set]').forEach(b=>{const id=b.dataset.set,s=data.climaxRevision.sets.find(x=>x.id===id);if(!s)return;const card=b.closest('.set');b.removeAttribute('data-set');b.dataset.climaxSet=id;b.disabled=false;b.textContent='▶ 새 클라이맥스';const old=card.querySelectorAll('.track')[1];if(old){const details=document.createElement('details');details.className='old-climax';details.innerHTML='<summary>이전 클라이맥스 v1과 비교</summary>';old.before(details);details.append(old);const row=document.createElement('div');row.className='track';row.innerHTML='<div class="trackinfo"><span class="role">클라이맥스 · 긴장형 v2</span><small>새 Suno 후보 · 페이지 안에서 비교</small></div><button class="pill" data-climax-set="'+id+'">A/B 듣기</button>';details.before(row);}});}
document.getElementById('climax-select').addEventListener('change',e=>showClimax(e.target.value));document.querySelectorAll('[data-climax-genre]').forEach(b=>b.addEventListener('click',()=>showClimax(data.climaxRevision.sets.find(s=>s.genre===b.dataset.climaxGenre).id)));document.querySelectorAll('[data-climax-candidate]').forEach(b=>b.addEventListener('click',()=>showClimax(document.getElementById('climax-select').value,+b.dataset.climaxCandidate)));
document.getElementById('cards').addEventListener('click',e=>{const b=e.target.closest('[data-climax-set]');if(b){showClimax(b.dataset.climaxSet);document.getElementById('climax-revision').scrollIntoView({behavior:'smooth',block:'start'});}});
document.getElementById('pig-revision')?.addEventListener('click',silenceClimax,true);
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{silenceClimax();const genre=b.dataset.filter==='folktale'?'folktale':'classic';showClimax(data.climaxRevision.sets.find(s=>s.genre===genre).id);}));
enhanceClimaxCards();showClimax(data.climaxRevision.sets[0].id);
`};
};
